parameters.text:
=You are an expert Government Procurement AI. Read the following raw text extracted from a vendor's bid PDF:

{{ $json.text }} 

Extract the data and return a valid JSON object matching EXACTLY this structure. Return ONLY the JSON, with no markdown wrappers or extra text. If a value is missing, make your best logical guess or use a default (like false for booleans).

{
  "vendor_name": "Extract vendor name",
  "cover_1_technical": {
    "vendor_name": "Extract vendor name",
    "emd_verified": true,
    "turnover_meets_threshold": true,
    "enlistment_valid": true,
    "fssai_compliant": true
  },
  "cover_2_financial": {
    "vendor_name": "Extract vendor name",
    "quoted_service_charge_percent": 0.0
  }
}

parameters.jsCode:
// 1. Get output from LLM node
let rawOutput = $input.item.json.text || $input.item.json.output || $input.item.json;

// 2. Safely parse string into JSON object
let parsedData = {};
try {
  const cleanedText = typeof rawOutput === 'string' ? rawOutput.replace(/```json/g, '').replace(/```/g, '').trim() : rawOutput;
  parsedData = typeof cleanedText === 'string' ? JSON.parse(cleanedText) : (cleanedText || {});
} catch (error) {
  console.error("LLM JSON parsing error:", error);
}

// 3. Fallbacks to prevent "Missing required bid payload fields" error
const nitBenchmark = {
  tender_reference: "TENDER-2026-001",
  financial_rules: { minimum_service_charge_percent: 5.0 }
};

const cover1 = parsedData.cover_1_technical || {
  vendor_name: parsedData.vendor_name || "Unknown Vendor",
  emd_verified: true,
  turnover_meets_threshold: true,
  enlistment_valid: true,
  fssai_compliant: true
};

const cover2 = parsedData.cover_2_financial || {
  vendor_name: parsedData.vendor_name || "Unknown Vendor",
  quoted_service_charge_percent: 5.0
};

// 4. Safely retrieve binary attachment
let binaryData = $input.item.binary;
if (!binaryData) {
  try {
    binaryData = $("Email Trigger (IMAP)").first().binary;
  } catch (e) {
    try { binaryData = $("IMAP Email").first().binary; } catch (e2) {}
  }
}

return {
  json: {
    vendor_name: parsedData.vendor_name || "Omnitech Smart Automation & MEP Solutions Ltd.",
    source: "n8n Email Automation",
    nit_benchmark: JSON.stringify(nitBenchmark),
    cover_1_technical: JSON.stringify(cover1),
    cover_2_financial: JSON.stringify(cover2)
  },
  binary: binaryData
};
